function UIMain_AttackBtn:__init()
    self.controller = nil
end


function UIMain_AttackBtn:__delete()
end



function UIMain_AttackBtn:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end


function UIMain_AttackBtn:Start()
    KTool.SetActive(self.controller.gameObject, true)


    self.attackButton    = KTool.GetComponent( self.controller.gameObject, typeof(Button) )
    self.attackAnimation = KTool.GetComponent( self.controller.gameObject, typeof(Animation) )
    assert( self.attackButton and self.attackAnimation )

        
    self.attackAnimation:Play( ButtonIdle )
    self.attackButton.onClick:AddListener( Bind(self, self.OnPress) )
end




function UIMain_AttackBtn:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function UIMain_AttackBtn:OnPress()
    if self.attackAnimation.isPlaying == true then
        print("正在播放")
        return
    end
    self.attackAnimation:Play( ButtonPressed )
end






return UIMain_AttackBtn

